mapper.select:
SELECT COLLECTION_ID,
       CONTENT_ID,
       TO_CHAR(ADDED_DT, 'YYYY-MM-DD HH24:MI:SS') AS ADDED_DT
  FROM COLLECTION_ITEM
 WHERE COLLECTION_ID = #{collectionId}
   AND CONTENT_ID = #{contentId}

mapper.delete:
DELETE FROM COLLECTION_ITEM
 WHERE COLLECTION_ID = #{collectionId}
   AND CONTENT_ID = #{contentId}
